import type { RetryPolicy } from './retry-policy';

export interface RetryContext<T> {
    attempt: number;
    totalElapsedMs: number;
    lastResult?: T;
}

export interface IRetryService<T> {
    applyRetry(operation: () => Promise<T>, retryPolicyOverride?: RetryPolicy<T>): Promise<T>;
}

export class RetryService<T> implements IRetryService<T> {
    constructor(private readonly defaultRetryPolicy: RetryPolicy<T>) {}

    applyRetry(operation: () => Promise<T>, retryPolicyOverride?: RetryPolicy<T>): Promise<T> {
        return this.retry(operation, retryPolicyOverride || this.defaultRetryPolicy);
    }

    protected async retry(operation: () => Promise<T>, policy: RetryPolicy<T>): Promise<T> {
        const startTime = Date.now();

        let attempt = 0;
        let result: T = await operation();
        let context: RetryContext<T> = {
            attempt,
            totalElapsedMs: Date.now() - startTime,
            lastResult: result,
        };

        while (await policy.shouldRetry(result, context)) {
            const delay = await policy.calculateDelay(result, context);
            await this.delay(delay);

            // Call prepareRetry hook if policy implements it
            if (policy.prepareRetry) {
                await policy.prepareRetry(result, context);
            }

            attempt++;
            result = await operation();
            context = {
                attempt,
                totalElapsedMs: Date.now() - startTime,
                lastResult: result,
            };
        }

        return result;
    }

    private delay(ms: number): Promise<void> {
        return new Promise((resolve) => {
            setTimeout(resolve, ms);
        });
    }
}
